  "code": "def generated_loss(batch, model_output, extra):
    # Helper to fetch a tensor/scalar from multiple possible locations.
    def _get(key, default=None):
        if isinstance(extra, dict) and key in extra:
            return extra[key]
        if isinstance(model_output, dict) and key in model_output:
            return model_output[key]
        if isinstance(batch, dict) and key in batch:
            return batch[key]
        return default

    log_prob_w = _get("log_prob_w", None)
    log_prob_l = _get("log_prob_l", None)

    # If canonical keys are missing, try common aliases.
    if log_prob_w is None:
        log_prob_w = _get("logp_w", _get("chosen_logp", _get("logprob_w", _get("log_prob_chosen", None))))
    if log_prob_l is None:
        log_prob_l = _get("logp_l", _get("rejected_logp", _get("logprob_l", _get("log_prob_rejected", None))))

    base_weight = _get("weight", None)

    hp = {}
    if isinstance(extra, dict):
        hp = extra.get("hyperparams", {}) or {}

    alpha = float(_get("alpha", hp.get("alpha", 1.0)))
    tau0 = float(_get("tau0", hp.get("tau0", 0.5)))
    tau1 = float(_get("tau1", hp.get("tau1", 0.5)))
    g_max = float(_get("g_max", hp.get("g_max", 3.0)))
    k = float(_get("k", hp.get("k", 0.5)))
    w_min = float(_get("w_min", hp.get("w_min", 0.25)))
    w_max = float(_get("w_max", hp.get("w_max", 4.0)))
    eps = float(_get("eps", hp.get("eps", 1e-8)))

    # Require log-probs; if missing, return a safe zero anchored to an available tensor.
    if log_prob_w is None or log_prob_l is None:
        ref = None
        for t in [base_weight, _get("delta_z", None)]:
            if t is not None:
                ref = t
                break
        if ref is None:
            return ops.zeros(())
        return ref.sum() * 0.0

    d = log_prob_w - log_prob_l

    # Objective gap signal used for adaptive temperature/weighting.
    delta_z = _get("delta_z", None)
    if delta_z is None:
        g_n = d * 0.0
    else:
        g_n = ops.zscore(delta_z, eps=eps)

    g_mag = ops.clamp(ops.abs(g_n), 0.0, g_max)
    tau = ops.softplus(tau0) + tau1 * g_mag

    w = ops.clamp(1.0 + k * g_mag, w_min, w_max)
    if base_weight is not None:
        w = w * base_weight

    loss_vec = w * ops.softplus(-alpha * d / (tau + eps))
    return loss_vec.mean()",
